SET LOCAL search_path = "chat", pg_catalog;
-- Coordinator review proposal only. Not a registered migration.
CREATE TABLE interaction_follows(follower text,followee text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(follower,followee));CREATE INDEX ON interaction_follows(followee,created_at DESC,follower DESC);CREATE INDEX ON interaction_follows(follower,created_at DESC,followee DESC);
 CREATE TABLE interaction_comments(id text PRIMARY KEY,pool text NOT NULL,author text NOT NULL,parent text REFERENCES interaction_comments(id),body text NOT NULL,depth int CHECK(depth BETWEEN 1 AND 4),removed boolean NOT NULL DEFAULT false,revision bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),edited_at timestamptz);
 CREATE TABLE interaction_reactions(actor text,target text REFERENCES interaction_comments(id),kind text CHECK(kind='like'),PRIMARY KEY(actor,target,kind));CREATE TABLE interaction_mutations(actor text,key text,payload bytea,PRIMARY KEY(actor,key));CREATE TABLE interaction_callout_refs(id text,revision bigint,actor text,metadata bytea,PRIMARY KEY(id,revision));CREATE TABLE interaction_notification_intents(target text,revision bigint,recipient text,PRIMARY KEY(target,revision,recipient));CREATE TABLE interaction_aggregate_revisions(aggregate_id text PRIMARY KEY,revision bigint NOT NULL CHECK(revision>0));
 CREATE TABLE interaction_comment_moderation(target text REFERENCES interaction_comments(id),revision bigint NOT NULL,actor text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(target,revision));
 CREATE TABLE interaction_outbox(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor text NOT NULL,action text NOT NULL,target text NOT NULL,aggregate_id text NOT NULL,revision bigint NOT NULL CHECK(revision>0),removed boolean NOT NULL,visibility text NOT NULL CHECK(visibility='public'),UNIQUE(aggregate_id,revision));
